From 65cea6282101d0035c21d4be2eb504c93b747fd8 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:29:23 +0100
Subject: [PATCH] containments/desktop: Don't reorder icons by dragging in
 sorted mode

Dropping an icon onto an empty spot of a sorted desktop silently
switched the sort mode to Unsorted, throwing away the order the user had
picked. Sort modes now stay as they are and the icon goes back in place.

BUG: 413499
---
 .../desktop/plugins/folder/foldermodel.cpp    | 21 +------------------
 .../desktop/plugins/folder/foldermodel.h      |  6 ------
 .../desktop/plugins/folder/positioner.cpp     |  8 +------
 3 files changed, 2 insertions(+), 33 deletions(-)

diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..0ffb131eb2 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -408,17 +408,6 @@ void FolderModel::newFileMenuItemRejected(const QUrl &url)
     setCreatingNewItems(false);
 }

-void FolderModel::setUnsortedModeOnDrop()
-{
-    // The positioner will override old icon layout by
-    // sorted icon layout after drag and drop operation.
-    if (m_sortMode != -1) {
-        m_unsortedModeOnDrop = true;
-        setSortMode(-1);
-        m_unsortedModeOnDrop = false;
-    }
-}
-
 QString FolderModel::url() const
 {
     return m_url;
@@ -1360,12 +1349,10 @@ void FolderModel::drop(QQuickItem *target, QObject *dropEvent, int row, bool sho
     const QPoint dropPos = {x, y};

     if (dragging() && row == -1 && !m_urlChangedWhileDragging) {
-        if (m_locked || mimeData->urls().isEmpty()) {
+        if (m_locked || m_sortMode != -1 || mimeData->urls().isEmpty()) {
             return;
         }

-        setUnsortedModeOnDrop();
-
         for (const auto &url : mimeData->urls()) {
             m_dropTargetPositions.insert(url.fileName(), dropPos);
             m_screenMapper->addMapping(mappableUrl(url), m_screen, m_currentActivity, ScreenMapper::DelayedSignal);
@@ -1388,7 +1375,6 @@ void FolderModel::drop(QQuickItem *target, QObject *dropEvent, int row, bool sho

     if (m_usedByContainment && !m_screenMapper->sharedDesktops()) {
         if (isDropBetweenSharedViews(mimeData->urls(), dropTargetUrl)) {
-            setUnsortedModeOnDrop();
             const QList<QUrl> urls = mimeData->urls();
             for (const auto &url : urls) {
                 m_dropTargetPositions.insert(url.fileName(), dropPos);
@@ -2355,11 +2341,6 @@ QRectF FolderModel::screenGeometry()
     return QRectF();
 }

-bool FolderModel::unsortedModeOnDrop()
-{
-    return m_unsortedModeOnDrop;
-}
-
 bool FolderModel::creatingNewItems() const
 {
     return m_creatingNewItems;
diff --git a/containments/desktop/plugins/folder/foldermodel.h b/containments/desktop/plugins/folder/foldermodel.h
index c2a2a388f9..6b2f3ab1d3 100644
--- a/containments/desktop/plugins/folder/foldermodel.h
+++ b/containments/desktop/plugins/folder/foldermodel.h
@@ -288,8 +288,6 @@ public:
 #endif
     QRectF screenGeometry();

-    bool unsortedModeOnDrop();
-
 Q_SIGNALS:
     void urlChanged() const;
     void listingCompleted(const QList<QUrl> &items) const;
@@ -348,9 +346,6 @@ private Q_SLOTS:
     void newFileMenuItemCreated(const QUrl &url);
     void newFileMenuItemRejected(const QUrl &url);

-private:
-    void setUnsortedModeOnDrop();
-
 private:
     struct DragImage {
         int row;
@@ -415,7 +410,6 @@ private:
     bool m_complete;
     QPoint m_menuPosition;
     bool m_creatingNewItems = false;
-    bool m_unsortedModeOnDrop = false;

     /**
      * This property is used to save the current activity when FolderModel is initialized.
diff --git a/containments/desktop/plugins/folder/positioner.cpp b/containments/desktop/plugins/folder/positioner.cpp
index 8fc7ec4c6c..1441cfa2d4 100644
--- a/containments/desktop/plugins/folder/positioner.cpp
+++ b/containments/desktop/plugins/folder/positioner.cpp
@@ -117,8 +117,7 @@ void Positioner::setPerStripe(int perStripe)
             m_perStripe = perStripe;
             Q_EMIT perStripeChanged();
         }
-        const bool unsortedModeOnDrop = m_folderModel->unsortedModeOnDrop();
-        if (m_enabled && (perStripeUpdated || resolutionUpdated) && !unsortedModeOnDrop) {
+        if (m_enabled && (perStripeUpdated || resolutionUpdated)) {
             const bool existingResolution = configurationHasResolution(m_resolution);
             if (existingResolution) {
                 loadAndApplyPositionsConfig();
@@ -143,11 +142,6 @@ void Positioner::setPerStripe(int perStripe)
             } else {
                 m_deferRestoreChangedPositions = true;
             }
-        } else if (m_enabled && unsortedModeOnDrop) {
